/// <summary>
/// The NDXSysDataBaseLogItemWeightBatchJob class handles processing retriving NetWeithChange from SysDatabaseLog in a batch.
/// </summary>
class NDXSysDataBaseLogItemWeightBatchJob extends RunBaseBatch implements BatchRetryable
{
    // Packed variables
    int                 dummy;

    // Dialog fields
    DialogField         dlgItemId;
    DialogField         dlgOnlyNew;


    ItemIdBase          itemId = '';
    boolean             onlyNew = false;

    #define.CurrentVersion(2)

}

Method.Source:
public ItemIdBase parmItemId(ItemIdBase _itemId = itemId)
{
    itemId = _itemId;
    return ItemId;
}

/// <summary>
/// Adds the <c>SalesID</c> to the dialog box
/// allowing the user to run a batch over the selected
/// <c>SalesID</c>.
/// </summary>
/// <returns>
/// The dialog box box.
/// </returns>
public Object dialog()
{
    DialogRunbase dialog;

    //Setup the dialog
    dialog = super();
    dialog.caption("@NDX:NDXSysDataBaseLogItemWeightBatchJob");

    dlgItemId = dialog.addField(extendedtypestr(ItemIdBase), "@NDX:NDXItemId" );
    dlgItemId.value(itemId);

    dlgOnlyNew = dialog.addField(extendedtypestr(NoYesId), "@NDX:OnlyNew" );
    dlgOnlyNew.value(onlyNew);

    return dialog;
}

/// <summary>
/// Retrieves the user entered values from dialog form.
/// </summary>
/// <returns>
/// true if the values are retrieved successfully; otherwise, false.
/// </returns>
public boolean getFromDialog()
{
    boolean ret;

    ret = super();
    if (dlgItemId && dlgItemId.value())
    {
        itemId = dlgItemId.value();
    }

    if (dlgOnlyNew)
    {
        onlyNew = dlgOnlyNew.value();
    }

    return ret;
}

public container pack()
{
    return [#CurrentVersion, itemId, onlyNew];
}

public boolean unpack(container packedClass)
{
    Version version = runbase::getVersion(packedClass);
    switch (version)
    {
        case #CurrentVersion:
            [version, itemId, onlyNew] = packedClass;
            break;
        default:
            return false;
    }

    return true;
}

/// <summary>
///  dialog prompt
/// </summary>
/// <returns>true or fals if dialog did open</returns>
boolean prompt()
{
    return super();
}

/// <summary>
/// Processes automatic notification events.
/// </summary>
/// <remarks>
/// When this job runs, it captures the current date when it starts.
/// Even if the job run time spans multiple days, it will still act as if it
/// was run all on the first day.
/// </remarks>
/// <exception cref="Exception::Error">
/// If the validation fails; throws an error.
/// </exception>
/// <exception cref="Exception::Error">
/// If the automatic notification event action is not supported; throws an error.
/// </exception>
public void run()
{
    InventTable lInventTable;
    NDXSysDataBaseLog lNDXSysDataBaseLog = new  NDXSysDataBaseLogItemWeightClass();

    if (itemId != '')
    {
        lInventTable =  InventTable::find(itemId);
    }

    lNDXSysDataBaseLog.getInfo_ItemTable(fieldNum(InventTable, NetWeight), this.onlyNew, lInventTable.RecId);
}

/// <summary>
/// show query values
/// </summary>
/// <returns>true or false</returns>
public boolean showQueryValues()
{
    return true;
}

/// <summary>
/// Constructor
/// </summary>
/// <returns>NDXSysDataBaseLogItemWeightBatchJob object</returns>
public static NDXSysDataBaseLogItemWeightBatchJob construct()
{
    return new NDXSysDataBaseLogItemWeightBatchJob();
}

/// <summary>
/// batch descritpion
/// </summary>
/// <returns>description</returns>
public static ClassDescription description()
{
    return "@NDX:NDXSysDataBaseLogItemWeightBatchJob";
}

public static void main(Args _args)
{
    NDXSysDataBaseLogItemWeightBatchJob lNDXSysDataBaseLogItemWeightBatchJob = new NDXSysDataBaseLogItemWeightBatchJob();
    InventTable lInventTable;
    lNDXSysDataBaseLogItemWeightBatchJob.parmInBatch(false);

    if(_args.dataset() == tableNum(InventTable) && _args.record() != null)
    {
        lInventTable = _args.record();
        lNDXSysDataBaseLogItemWeightBatchJob.parmItemId(lInventTable.ItemId);
    }

    if (lNDXSysDataBaseLogItemWeightBatchJob.prompt())
    {
        lNDXSysDataBaseLogItemWeightBatchJob.runOperation();
    }
}

/// <summary>
/// Describes whether the class is designed for execution in a new session.
/// </summary>
/// <returns>
/// false.
/// </returns>
protected boolean canRunInNewSession()
{
    return false;
}

/// <summary>
/// runs impersonated
/// </summary>
/// <returns>true or false</returns>
public boolean runsImpersonated()
{
    return true;
}

/// <summary>
/// Specifies if the batch task is retryable for transient exceptions or not.
/// </summary>
/// <returns>
/// If true is returned, the batch task is retryable, otherwise it is not.
/// </returns>
[Hookable(false)]
final boolean isRetryable() 
{
    return true;
}

/// <summary>
/// can go  batch
/// </summary>
/// <returns>true or false</returns>
public boolean canGoBatch()
{
    return true;
}
